import{_ as a,o,c as i,ah as t}from"./chunks/framework.ojwJKwrc.js";const p=JSON.parse('{"title":"Heliodor Linux Benchmark","description":"","frontmatter":{},"headers":[],"relativePath":"benchmarks/heliodor.md","filePath":"benchmarks/heliodor.md"}'),s={name:"benchmarks/heliodor.md"};function r(n,e,l,h,c,d){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="heliodor-linux-benchmark" tabindex="-1">Heliodor Linux Benchmark <a class="header-anchor" href="#heliodor-linux-benchmark" aria-label="Permalink to &quot;Heliodor Linux Benchmark&quot;">​</a></h1><p>Heliodor is Celox&#39;s large external Veryl workload. It boots a pinned Linux image and compares Celox&#39;s native backend with synchronous <code>veryl-cc</code> execution using the same design revision and input workload. Cranelift Linux boot measurements are not collected or published because their runtime is outside the useful scale of this comparison.</p><h2 id="what-the-benchmark-answers" tabindex="-1">What the benchmark answers <a class="header-anchor" href="#what-the-benchmark-answers" aria-label="Permalink to &quot;What the benchmark answers&quot;">​</a></h2><p>The benchmark separates two questions:</p><ol><li>How long does Celox take to compile the design?</li><li>How quickly does the generated simulator execute the complete workload?</li></ol><p>Only the second measurement is used for generated-code throughput comparisons. A partial boot, projected completion time, or compile-only result is not a successful execution result.</p><h2 id="valid-result" tabindex="-1">Valid result <a class="header-anchor" href="#valid-result" aria-label="Permalink to &quot;Valid result&quot;">​</a></h2><p>A run is accepted only when it:</p><ul><li>uses the pinned Heliodor and workload revisions;</li><li>reaches the configured Linux completion marker;</li><li>records compilation and execution separately;</li><li>compares runners built from the intended Celox and Veryl revisions;</li><li>preserves the logs needed to diagnose a timeout or semantic mismatch.</li></ul><p>This fixed completion marker prevents faster failures or incomplete boots from being reported as performance improvements.</p><h2 id="run-locally" tabindex="-1">Run locally <a class="header-anchor" href="#run-locally" aria-label="Permalink to &quot;Run locally&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/run-heliodor-bench.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p>The first run needs network access to obtain the pinned Heliodor checkout. The script prints the selected revisions, build configuration, completion status, and timings. Use the same machine and configuration for before/after comparisons.</p><p>Published results appear in the <strong>Heliodor Linux</strong> section of the <a href="./">benchmark dashboard</a>.</p>',14)])])}const m=a(s,[["render",r]]);export{p as __pageData,m as default};
